package thaumcraft.knowledge;

import net.minecraft.ChatFormatting;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.effect.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.entity.living.LivingEntityUseItemEvent;
import net.neoforged.neoforge.event.entity.player.PlayerEvent;
import net.neoforged.neoforge.event.tick.PlayerTickEvent;
import net.neoforged.neoforge.network.PacketDistributor;
import thaumcraft.api.aspects.Aspects;
import thaumcraft.effects.*;
import thaumcraft.config.ThaumcraftConfig;

/** TC4's decaying warp counter, exact event brackets and research thresholds. */
@EventBusSubscriber(modid="thaumcraft")
public final class WarpService {
    @SubscribeEvent public static void tick(PlayerTickEvent.Post event){if(!(event.getEntity() instanceof ServerPlayer player))return;if(player.tickCount>0&&player.tickCount%2000==0&&!ThaumcraftConfig.WUSS_MODE.get()&&!player.hasEffect(WarpEffects.WARP_WARD))check(player);if(player.tickCount%10==0&&player.hasEffect(WarpEffects.DEATH_GAZE))gaze(player);}
    @SubscribeEvent public static void crafted(PlayerEvent.ItemCraftedEvent event){if(event.getEntity() instanceof ServerPlayer player)crafted(player,event.getCrafting());}
    public static void crafted(ServerPlayer player,ItemStack stack){if(ThaumcraftConfig.WUSS_MODE.get())return;var id=BuiltInRegistries.ITEM.getKey(stack.getItem()).toString();if(java.util.Set.of("thaumcraft:focus_hellbat","thaumcraft:sinister_stone","thaumcraft:brain_in_a_jar","thaumcraft:flesh_golem","thaumcraft:focus_primal","thaumcraft:primal_staff_rod").contains(id))add(player,0,1,0);}
    public static void add(ServerPlayer player,int permanent,int sticky,int temporary){
        if(ThaumcraftConfig.WUSS_MODE.get())return;
        // get() returns the live store object; copy it so the diff survives the mutation.
        var before=KnowledgeService.get(player).copy();
        boolean ok=KnowledgeService.mutate(player,k->{int p=Math.max(0,k.permanentWarp()+permanent),s=Math.max(0,k.stickyWarp()+sticky),t=Math.max(0,k.temporaryWarp()+temporary);k.setWarp(p,s,t,p+s+t);return permanent!=0||sticky!=0||temporary!=0;});
        if(!ok)return;
        var after=KnowledgeService.get(player);
        // Original sends one PacketWarpMessage per tier that changed; gain whispers only on perm/sticky.
        if(after.permanentWarp()>before.permanentWarp())thaumcraft.network.Notify.warp(player,"tc.addwarp");
        if(after.stickyWarp()>before.stickyWarp())thaumcraft.network.Notify.warp(player,"tc.addwarpsticky");
        if(after.temporaryWarp()!=before.temporaryWarp())thaumcraft.network.Notify.purple(player,after.temporaryWarp()>before.temporaryWarp()?"tc.addwarptemp":"tc.removewarptemp");
    }
    private static void message(ServerPlayer player,String key){thaumcraft.network.Notify.purple(player,key);}
    private static void research(ServerPlayer player,int times){
        if(times<1)return;
        KnowledgeService.mutate(player,k->{int amount=1+player.getRandom().nextInt(times);for(int i=0;i<amount;i++)k.addPool(Aspects.PRIMALS.get(player.getRandom().nextInt(6)),1);return true;});
    }
    public static int gearWarp(Player player){int total=warp(player.getMainHandItem(),player);for(var stack:player.getArmorSlots())total+=warp(stack,player);for(var equipped:thaumcraft.items.EquippedCurios.stacks(player))total+=warp(equipped,player);return total;}
    private static int warp(ItemStack stack,Player player){int result=stack.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getInt("warp");if(stack.getItem() instanceof thaumcraft.api.IWarpingGear gear)result+=gear.getWarp(stack,player);if(stack.getItem() instanceof thaumcraft.items.BottleTaintItem)result++;if(stack.getItem() instanceof thaumcraft.items.ThaumicTools.Crusher)result+=2;if(stack.getItem() instanceof thaumcraft.items.ThaumicArmorItem armor){if(armor.kind()==thaumcraft.items.ThaumicArmorItem.Kind.VOID)result++;if(armor.kind()==thaumcraft.items.ThaumicArmorItem.Kind.VOID_ROBE)result+=2;}if(stack.getItem() instanceof TieredItem&&BuiltInRegistries.ITEM.getKey(stack.getItem()).getPath().startsWith("void_"))result++;return Math.max(0,result);}
    public static void check(ServerPlayer player){var k=KnowledgeService.get(player);int counter=k.warpCounter(),actual=k.permanentWarp()+k.stickyWarp(),total=k.totalWarp()+gearWarp(player);boolean trigger=counter>0&&total>0&&player.getRandom().nextInt(100)<=Math.sqrt(counter);if(trigger){int amount=Math.max(1,Math.min(100,(total*2+counter)/3));int reduced=(int)(counter-Math.max(5,Math.sqrt(counter)*2));KnowledgeService.mutate(player,state->{state.setWarp(state.permanentWarp(),state.stickyWarp(),state.temporaryWarp(),reduced);return true;});int effect=player.getRandom().nextInt(amount);if(thaumcraft.equipment.FortressArmor.mask(player.getItemBySlot(EquipmentSlot.HEAD))==0)effect-=2+player.getRandom().nextInt(4);dispatch(player,effect,amount);
            KnowledgeService.mutate(player,state->{boolean changed=false;if(actual>10&&!state.completedResearch().contains("BATHSALTS"))changed|=state.completeResearch("@BATHSALTS");if(actual>25&&!state.completedResearch().contains("ELDRITCHMINOR")){grant(state,player,10);changed|=state.completeResearch("ELDRITCHMINOR");}if(actual>50&&!state.completedResearch().contains("ELDRITCHMAJOR")){grant(state,player,20);changed|=state.completeResearch("ELDRITCHMAJOR");}return changed;});
        }KnowledgeService.mutate(player,state->{if(state.temporaryWarp()<=0)return false;state.setWarp(state.permanentWarp(),state.stickyWarp(),state.temporaryWarp()-1,state.warpCounter());return true;});}
    private static void grant(thaumcraft.api.knowledge.PlayerKnowledge state,ServerPlayer player,int times){for(int i=0,n=1+player.getRandom().nextInt(times);i<n;i++)state.addPool(Aspects.PRIMALS.get(player.getRandom().nextInt(6)),1);}
    private static void potion(ServerPlayer player,net.minecraft.core.Holder<MobEffect> effect,int duration,int amplifier){var instance=new MobEffectInstance(effect,duration,amplifier,!effect.is(WarpEffects.INFECTIOUS_EXHAUST.getId()),true);if(effect.is(TaintEffects.VIS_EXHAUST.getId())||effect.is(WarpEffects.THAUMARHIA.getId())||effect.is(WarpEffects.UNNATURAL_HUNGER.getId())||effect.is(WarpEffects.SUN_SCORNED.getId())||effect.is(WarpEffects.INFECTIOUS_EXHAUST.getId())||effect.is(WarpEffects.DEATH_GAZE.getId()))instance.getCures().clear();player.addEffect(instance);}
    public static void dispatch(ServerPlayer player,int effect,int amount){int amplifier=Math.min(3,amount/15);if(effect<=0)return;if(effect<=4){research(player,1);message(player,"warp.text.3");}else if(effect<=8){}else if(effect<=12)message(player,"warp.text.11");else if(effect<=16){potion(player,TaintEffects.VIS_EXHAUST,5000,amplifier);message(player,"warp.text.1");}else if(effect<=20){potion(player,WarpEffects.THAUMARHIA,Math.min(32000,10*amount),0);message(player,"warp.text.15");}else if(effect<=24){potion(player,WarpEffects.UNNATURAL_HUNGER,5000,amplifier);message(player,"warp.text.2");}else if(effect<=28)message(player,"warp.text.12");else if(effect<=32)mist(player,1);else if(effect<=36)potion(player,WarpEffects.BLURRED_VISION,Math.min(32000,10*amount),0);else if(effect<=40){potion(player,WarpEffects.SUN_SCORNED,5000,amplifier);message(player,"warp.text.5");}else if(effect<=44){potion(player,MobEffects.DIG_SLOWDOWN,1200,amplifier);message(player,"warp.text.9");}else if(effect<=48){potion(player,WarpEffects.INFECTIOUS_EXHAUST,6000,amplifier);message(player,"warp.text.1");}else if(effect<=52){potion(player,MobEffects.NIGHT_VISION,Math.min(40*amount,6000),0);message(player,"warp.text.10");}else if(effect<=56){potion(player,WarpEffects.DEATH_GAZE,6000,amplifier);message(player,"warp.text.4");}else if(effect<=60)spiders(player,amount,false);else if(effect<=64)message(player,"warp.text.13");else if(effect<=68)mist(player,amount/30);else if(effect<=72)potion(player,MobEffects.BLINDNESS,Math.min(32000,5*amount),0);else if(effect==76){KnowledgeService.mutate(player,k->{if(k.stickyWarp()<=0)return false;k.setWarp(k.permanentWarp(),k.stickyWarp()-1,k.temporaryWarp(),k.permanentWarp()+k.stickyWarp()-1+k.temporaryWarp());return true;});message(player,"warp.text.14");}else if(effect<=80){potion(player,WarpEffects.UNNATURAL_HUNGER,6000,amplifier);message(player,"warp.text.2");}else if(effect<=84){research(player,amount/10);message(player,"warp.text.3");}else if(effect>88){if(effect<=92)spiders(player,amount,true);else mist(player,amount/15);}}
    private static boolean place(ServerPlayer player,Mob mob){var level=player.serverLevel();var origin=player.blockPosition();for(int tries=0;tries<50;tries++){var random=level.random;var pos=origin.offset((7+random.nextInt(18))*(random.nextInt(3)-1),(7+random.nextInt(18))*(random.nextInt(3)-1),(7+random.nextInt(18))*(random.nextInt(3)-1));if(!level.hasChunkAt(pos)||!level.getBlockState(pos.below()).isFaceSturdy(level,pos.below(),net.minecraft.core.Direction.UP))continue;mob.moveTo(pos.getX()+.5,pos.getY(),pos.getZ()+.5,random.nextFloat()*360,0);if(!level.noCollision(mob)||level.containsAnyLiquid(mob.getBoundingBox()))continue;mob.setTarget(player);return level.addFreshEntity(mob);}return false;}
    private static void mist(ServerPlayer player,int count){PacketDistributor.sendToPlayer(player,new thaumcraft.network.GuardianMistPayload());for(int i=0;i<Math.min(8,count);i++){var guardian=thaumcraft.entities.R2Entities.ELDRITCH_GUARDIAN.get().create(player.level());if(guardian!=null)place(player,guardian);}message(player,"warp.text.6");}
    private static void spiders(ServerPlayer player,int amount,boolean real){for(int i=0;i<Math.min(50,amount);i++){var spider=thaumcraft.entities.R3Entities.MIND_SPIDER.get().create(player.level());if(spider==null)continue;if(!real)spider.illusion(player);place(player,spider);}message(player,"warp.text.7");}
    private static void gaze(ServerPlayer player){var effect=player.getEffect(WarpEffects.DEATH_GAZE);int range=Math.min(8+effect.getAmplifier()*3,24);for(var target:player.level().getEntitiesOfClass(LivingEntity.class,player.getBoundingBox().inflate(range))){if(target==player||!target.isAlive()||target.hasEffect(MobEffects.WITHER)||target instanceof Player&&!player.server.isPvpAllowed()||!player.hasLineOfSight(target))continue;var vector=target.getBoundingBox().getCenter().subtract(player.getEyePosition());if(player.getLookAngle().dot(vector)>=range||player.getLookAngle().dot(vector.normalize())<=Math.cos(.375))continue;target.setLastHurtByMob(player);if(target instanceof Mob mob)mob.setTarget(player);target.addEffect(new MobEffectInstance(MobEffects.WITHER,80));}}
    @SubscribeEvent public static void food(LivingEntityUseItemEvent.Finish event){if(!(event.getEntity() instanceof ServerPlayer player)||!player.hasEffect(WarpEffects.UNNATURAL_HUNGER))return;var item=event.getItem();if(item.is(Items.ROTTEN_FLESH)||item.is(thaumcraft.registry.R2Content.ZOMBIE_BRAIN.get())){var effect=player.getEffect(WarpEffects.UNNATURAL_HUNGER);int duration=effect.getDuration()-600,amplifier=effect.getAmplifier()-1;player.removeEffect(WarpEffects.UNNATURAL_HUNGER);if(duration>0&&amplifier>=0)potion(player,WarpEffects.UNNATURAL_HUNGER,duration,amplifier);thaumcraft.network.Notify.send(player,"warp.text.hunger.2","",0x00aa00,true);}else if(item.has(net.minecraft.core.component.DataComponents.FOOD))thaumcraft.network.Notify.send(player,"warp.text.hunger.1","",0xaa0000,true);}
    private WarpService(){}
}
